import{_ as t,o as a,a as i,a2 as s}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Bagisto Frontend Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/frontend.md","filePath":"architecture/frontend.md","lastUpdated":1789331268000}'),o={name:"architecture/frontend.md"};function n(r,e,d,l,c,h){return a(),i("div",null,e[0]||(e[0]=[s(`<h1 id="bagisto-frontend-overview" tabindex="-1">Bagisto Frontend Overview <a class="header-anchor" href="#bagisto-frontend-overview" aria-label="Permalink to &quot;Bagisto Frontend Overview&quot;">​</a></h1><p>Bagisto&#39;s frontend leverages powerful tools and frameworks to create a dynamic, responsive, and visually appealing user interface. Designed to deliver a seamless shopping experience, Bagisto combines modern technologies and best practices to ensure optimal performance and flexibility.</p><h2 id="tailwind-css" tabindex="-1">Tailwind CSS <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind CSS&quot;">​</a></h2><p>Bagisto uses <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> for its styling needs. Tailwind CSS is a highly customizable, utility-first CSS framework that allows developers to build responsive and modern designs efficiently.</p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Customization</strong>: Tailwind CSS provides extensive configuration options, enabling developers to tailor the design system to specific project requirements</li><li><strong>Utility-First Approach</strong>: It offers utility classes that can be combined to create any design directly in your HTML</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>How Tailwind is configured depends on the release line:</p><ul><li><strong>Bagisto 2.5 (Tailwind 4)</strong>: there is no <code>tailwind.config.js</code>. Each package&#39;s <code>app.css</code> imports Tailwind and declares where to scan for classes with <code>@import &quot;tailwindcss&quot; source(&quot;../../../&quot;)</code>, defines design tokens in an <code>@theme {}</code> block, and registers the icon font&#39;s utilities with <code>@utility</code>. The <code>@tailwindcss/vite</code> plugin compiles it; there is no PostCSS step.</li><li><strong>Bagisto 2.4 (Tailwind 3)</strong>: each package carries a <code>tailwind.config.js</code> listing the Blade and JavaScript paths to scan, and a <code>postcss.config.cjs</code> runs Tailwind through PostCSS.</li></ul><p>Both shapes, with the exact files, are shown side by side on <a href="./../theme-development/vite-powered-theme-assets.html">Vite-Powered Theme Assets</a>.</p><h2 id="vue-js" tabindex="-1">Vue.js <a class="header-anchor" href="#vue-js" aria-label="Permalink to &quot;Vue.js&quot;">​</a></h2><p>The dynamic user interfaces in Bagisto are powered by <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a>, a robust and flexible JavaScript framework.</p><h3 id="key-features-1" tabindex="-1">Key Features <a class="header-anchor" href="#key-features-1" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Reactive Components</strong>: Vue.js enables the development of reactive components that update seamlessly as the data changes</li><li><strong>Component-Based Architecture</strong>: This promotes reusability and maintainability of code by breaking down the UI into isolated, reusable components</li></ul><p>Vue components are not compiled from <code>.vue</code> files. Each Blade component under <code>Resources/views/components/</code> registers its Vue component with an inline <code>&lt;script type=&quot;text/x-template&quot;&gt;</code> pushed onto the <code>scripts</code> stack, and the <a href="./../theme-development/blade-components.html">Blade Components</a> page documents the props of each. Forms use VeeValidate, as described on <a href="./../theme-development/validation.html">Validation</a>.</p><h3 id="build-tool-integration" tabindex="-1">Build Tool Integration <a class="header-anchor" href="#build-tool-integration" aria-label="Permalink to &quot;Build Tool Integration&quot;">​</a></h3><p>In conjunction with Vue.js, Bagisto uses <a href="https://vitejs.dev/" target="_blank" rel="noreferrer">Vite</a> as the build tool. Vite offers a fast and efficient development environment with hot module replacement.</p><p>Admin, Shop and Installer each have an independent Vite build, run from the package directory:</p><table tabindex="0"><thead><tr><th>Package</th><th>Source</th><th>Output</th></tr></thead><tbody><tr><td><code>packages/Webkul/Admin</code></td><td><code>src/Resources/assets/</code></td><td><code>public/themes/admin/default/build/</code></td></tr><tr><td><code>packages/Webkul/Shop</code></td><td><code>src/Resources/assets/</code></td><td><code>public/themes/shop/default/build/</code></td></tr><tr><td><code>packages/Webkul/Installer</code></td><td><code>src/Resources/assets/</code></td><td><code>public/themes/installer/default/build/</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/Webkul/Shop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or npm run build</span></span></code></pre></div><p>The root <code>vite.config.js</code> belongs to the Laravel skeleton and builds only <code>resources/css/app.css</code> and <code>resources/js/app.js</code>; Bagisto&#39;s own pages do not use it. A custom theme brings its own Vite config and declares its build in <code>config/themes.php</code>, and the <code>@bagistoVite</code> directive loads the right manifest for the active theme.</p><h2 id="blade" tabindex="-1">Blade <a class="header-anchor" href="#blade" aria-label="Permalink to &quot;Blade&quot;">​</a></h2><p>Bagisto utilizes the Blade template engine, which is integrated with <a href="https://laravel.com" target="_blank" rel="noreferrer">Laravel</a>. Blade allows developers to use both Blade components and plain PHP code within templates, providing flexibility and power for crafting dynamic and efficient solutions.</p><h3 id="key-features-2" tabindex="-1">Key Features <a class="header-anchor" href="#key-features-2" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Template Inheritance</strong>: Blade supports template inheritance, which allows for a modular and maintainable template structure</li><li><strong>Directives</strong>: Blade includes various directives that simplify common tasks, such as loops and conditionals</li><li><strong>Theme override</strong>: any view or component can be replaced by a theme without touching the package; see <a href="./../theme-development/creating-store-theme.html#how-views-are-resolved">Creating Store Theme</a></li><li><strong>Render events</strong>: <code>view_render_event()</code> hooks let a package inject markup into core pages; see <a href="./../advanced/view-render-events.html">View Render Events</a></li></ul>`,25)]))}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
